import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp_c = 0
    opp_d = 0
    for _, o in history:
        if o == 'C':
            opp_c += 1
        else:
            opp_d += 1

    recent = history[-12:] if n >= 12 else history
    rec_c = sum(1 for _, o in recent if o == 'C')
    rec_d = len(recent) - rec_c

    my_last, opp_last = history[-1]

    # Detect always-defect style opponent
    if opp_d == n and n >= 3:
        return 'D'

    # Detect mostly-defect recent opponent
    if rec_d >= len(recent) - 1 and len(recent) >= 5:
        return 'D'

    # If opponent almost always cooperates, mostly cooperate but exploit late/often enough
    if opp_c >= n * 0.9 and n >= 10:
        # occasional exploitation, more likely later
        if n >= 90:
            return 'D'
        if rng.random() < 0.12:
            return 'D'
        return 'C'

    # Aggressive but forgiving response to defection
    if opp_last == 'D':
        # If opponent has been generally cooperative, forgive sometimes
        if opp_c > opp_d and rec_d <= 2:
            if rng.random() < 0.45:
                return 'C'
        # If mutual defection recently, try to repair
        if my_last == 'D' and opp_last == 'D':
            if rec_d <= 4:
                if rng.random() < 0.25:
                    return 'C'
                return 'D'
            return 'D'
        return 'D'

    # opp_last == 'C'
    # If we defected and they still cooperated, they are forgiving; exploit sometimes
    if my_last == 'D':
        if opp_c >= n * 0.7 and rng.random() < 0.4:
            return 'D'
        return 'C'

    # Cooperative default, but if opponent has a nontrivial defection rate, be cautious
    if rec_d >= 4:
        return 'D'
    if rec_d >= 2 and rng.random() < 0.25:
        return 'D'

    return 'C'
